/usr/bin/zsh -lc "python - <<'PY'
import cv2
im=cv2.imread('images/fig_27.png');g=cv2.cvtColor(im,cv2.COLOR_BGR2GRAY)
c=cv2.HoughCircles(g,cv2.HOUGH_GRADIENT,1,8,param1=100,param2=13,minRadius=5,maxRadius=9)
pts=[]
if c is not None:
 for x,y,r in c[0]:
  if 107<x<614 and 35<y<280:pts.append([float(x),float(y)])
print(len(pts));import json;json.dump(pts,open('fig27_centers.json','w'))
for x,y in pts:cv2.circle(im,(round(x),round(y)),2,(0,0,255),-1)
cv2.imwrite('fig27_check.png',im)
PY"

